/** Config file loading with a guaranteed fallback to shared defaults (rule 6 lives in config.js). */
import { readFile } from "node:fs/promises";
import { DEFAULT_RETRIES } from "./config.js";

/**
 * Read and parse a JSON config file. A missing, unreadable, or malformed file
 * never throws: the shared defaults are returned instead, and any supplied
 * `opts.warn` callback receives a diagnostic describing the failure.
 * @param {string} path filesystem path to the JSON config file
 * @param {{ warn?: (message: string) => void }} [opts] optional diagnostics callback
 * @returns {Promise<object>} the parsed JSON contents, or `{ retries: DEFAULT_RETRIES }`
 */
export async function loadConfig(path, opts) {
  const warn = typeof opts?.warn === "function" ? opts.warn : null;
  try {
    const raw = await readFile(path, "utf8");
    return JSON.parse(raw);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    if (warn) warn(`loadConfig: falling back to defaults for ${path}: ${reason}`);
    return { retries: DEFAULT_RETRIES };
  }
}
```

Notes:
- Both `readFile` failures (missing/permission) and `JSON.parse` failures hit the same catch, returning `{ retries: DEFAULT_RETRIES }`.
- `DEFAULT_RETRIES` is imported from `src/config.js`; no URLs or secrets are inlined.
- The catch reports through the optional `opts.warn` callback with the full error text (no clipping) and otherwise falls back via its return value.
- Exported function carries a JSDoc `@returns` (rule 9); no `console.log`, no TODOs.

