```js
/** Loads a JSON config file, falling back to shared defaults when it is unusable. */
import { readFile } from "node:fs/promises";
import { DEFAULT_RETRIES } from "./config.js";

/**
 * Read and parse a JSON config file. A missing or malformed file is never
 * fatal: the shared defaults are returned instead and a diagnostic is emitted.
 * @param {string} path filesystem path to the JSON config
 * @param {{ warn?: (message: string, error: unknown) => void }} [opts] diagnostics sink
 * @returns {Promise<object>} the parsed config, or `{ retries: DEFAULT_RETRIES }`
 */
export async function loadConfig(path, opts = {}) {
  const warn = opts.warn ?? ((message, error) => console.warn(message, error));
  try {
    const raw = await readFile(path, "utf8");
    return JSON.parse(raw);
  } catch (error) {
    warn(`config: falling back to defaults for ${path}`, error);
    return { retries: DEFAULT_RETRIES };
  }
}
```

