/** Tax helpers for the fixture. */

const RATES = { DE: 0.19, US: 0.07 };

/**
 * Look up the tax rate for a country.
 * @returns {number} the rate, or 0 for unknown countries
 */
export function rateFor(country) {
  return RATES[country] ?? 0;
}

/**
 * Apply the country's tax to an amount in whole cents.
 * @returns {number} the total in whole cents
 */
